import type { ComponentProps, ReactNode } from "react";

import { describeSnippet, SnippetCard, type Snippet } from "@rhs-ui/marketing/ui-snippets-hero/cards";
import { cn } from "@/lib/utils";

export type { ActivitySnippet, CommentSnippet, Snippet, SnippetPerson, StatusSnippet, TaskSnippet } from "@rhs-ui/marketing/ui-snippets-hero/cards";

export interface UiSnippetsHeroProps extends Omit<ComponentProps<"section">, "title" | "children"> {
  /** The title's element: "h2" inside a page that has its own h1 (the default), "h1" when the hero opens the page. */
  titleAs?: "h1" | "h2";
  /** A short label above the title: "Now with shared views". */
  eyebrow?: string;
  /** The promise, in a line or two. */
  title: string;
  /** One line under the title. */
  description?: string;
  /** Two actions: the one you want pressed, and a quieter one. */
  actions?: ReactNode;
  /** Two or three cards for the side where a sentence starts: the left in a language read from left to right. A task, a comment, an activity toast or a status card each. */
  start: readonly Snippet[];
  /** Two or three cards for the other side. */
  end: readonly Snippet[];
  /** What a screen reader hears in place of the cards. One sentence per card, written from their own words, when left out. */
  summary?: string;
}

/* Written out so Tailwind sees every class. A card is moved sideways a little and each one by a different amount. Under 1280px they stay inside the page's own margin; wider, they move further, past the edge of the content. */
const START_SHIFT = ["lg:-translate-x-2 xl:-translate-x-10", "lg:translate-x-3 xl:-translate-x-1", "lg:-translate-x-1 xl:-translate-x-7"] as const;
const END_SHIFT = ["lg:translate-x-1 xl:translate-x-4", "lg:translate-x-2 xl:translate-x-10", "lg:-translate-x-2 xl:translate-x-6"] as const;
/* The two sides sit at different heights: the start side is lifted and the end side lowered, each as a whole, so no two cards on one side ever crowd each other. */
const START_SIDE = "lg:-translate-y-5";
const END_SIDE = "lg:translate-y-6";

/**
 * A product opening where small interface cards flank a centred headline, in
 * place of one big screenshot underneath. Each side holds two or three cards
 * described by data (a task with its assignee and due date, a comment with a
 * reply field, an activity toast, a status card) and drawn with the real
 * checkbox, badge and avatar, so they look like the product. The cards float
 * at different heights and are moved sideways by a few plain CSS translations,
 * with one soft shadow; on wide screens they bleed a little past the content.
 * To a screen reader they are one sentence, they are inert, and nothing in
 * them depends on a pointer. Below 1024px they gather in a quiet stack under
 * the actions, two columns on a tablet and, on a phone, the first two cards of
 * each side in one column. A calm alternative to a hero image for collaboration and
 * workflow tools: no glow, no glass and no gradient.
 */
export function UiSnippetsHero({ titleAs: Title = "h2", eyebrow, title, description, actions, start, end, summary, className, ...props }: UiSnippetsHeroProps) {
  return (
    <section
      data-slot="ui-snippets-hero"
      className={cn(
        "grid grid-cols-1 gap-y-12 py-16 text-center sm:py-20",
        "lg:grid-cols-[minmax(0,1fr)_minmax(0,28rem)_minmax(0,1fr)] lg:items-center lg:gap-x-8 lg:gap-y-0 lg:py-28 xl:grid-cols-[minmax(0,1fr)_minmax(0,32rem)_minmax(0,1fr)] xl:gap-x-12",
        className,
      )}
      {...props}
    >
      <div className="mx-auto flex max-w-2xl flex-col items-center lg:col-start-2 lg:row-start-1 lg:max-w-none">
        {eyebrow ? <p className="mb-5 text-xs font-medium tracking-[.14em] text-muted-foreground uppercase">{eyebrow}</p> : null}
        <Title className="text-4xl leading-[1.05] font-medium tracking-[-0.04em] text-balance sm:text-5xl">{title}</Title>
        {description ? <p className="mt-5 max-w-lg text-base leading-relaxed text-pretty text-muted-foreground sm:text-lg">{description}</p> : null}
        {actions ? <div className="mt-8 flex flex-wrap items-center justify-center gap-3">{actions}</div> : null}
      </div>

      <p className="sr-only">{summary ?? [...start, ...end].map(describeSnippet).join(" ")}</p>

      {/* Under 1024px the two sides are the two columns of a quiet stack; from 1024px the wrapper steps aside and each side becomes a column of the section's own grid. */}
      <div className="mx-auto grid w-full max-w-sm gap-3 sm:max-w-2xl sm:grid-cols-2 sm:gap-4 lg:contents">
        <div aria-hidden="true" inert className={cn("flex min-w-0 flex-col gap-3 sm:gap-4 lg:col-start-1 lg:row-start-1 lg:items-end lg:gap-5 lg:justify-self-end", START_SIDE)}>
          {start.map((snippet, index) => (
            <SnippetCard key={`${index}-${snippet.kind}`} snippet={snippet} className={cn("lg:max-w-60 xl:max-w-68", index > 1 && "max-sm:hidden", START_SHIFT[index % START_SHIFT.length])} />
          ))}
        </div>
        <div aria-hidden="true" inert className={cn("flex min-w-0 flex-col gap-3 sm:gap-4 lg:col-start-3 lg:row-start-1 lg:items-start lg:gap-5 lg:justify-self-start", END_SIDE)}>
          {end.map((snippet, index) => (
            <SnippetCard key={`${index}-${snippet.kind}`} snippet={snippet} className={cn("lg:max-w-60 xl:max-w-68", index > 1 && "max-sm:hidden", END_SHIFT[index % END_SHIFT.length])} />
          ))}
        </div>
      </div>
    </section>
  );
}

import { IconCalendar, IconCheck, IconSend } from "@rhs-ui/icons";
import { Avatar, AvatarFallback, AvatarImage, initialsOf } from "@rhs-ui/primitives/avatar";
import { Badge } from "@rhs-ui/primitives/badge";
import { Checkbox } from "@rhs-ui/primitives/checkbox";
import { cn } from "@/lib/utils";

export interface SnippetPerson {
  /** The name; it gives the initials. */
  name: string;
  /** A portrait. The initials show when it is left out or fails to load. */
  src?: string;
}

/** A task row: a check, a title, a label, the day it is due and who has it. */
export interface TaskSnippet {
  /** Tells the card kinds apart. */
  kind: "task";
  /** What is to be done: "Draft the Q4 launch brief". */
  title: string;
  /** Who it is assigned to. */
  assignee: SnippetPerson;
  /** The due date as you want it written: "Fri 14". */
  due: string;
  /** Draws the check as ticked and the title struck through. */
  done?: boolean;
  /** A word for the project or the kind of work: "Marketing". */
  label?: string;
}

/** A comment with a reply field under it. */
export interface CommentSnippet {
  /** Tells the card kinds apart. */
  kind: "comment";
  /** Who wrote it. */
  author: SnippetPerson;
  /** What they said, in a sentence or two. */
  text: string;
  /** How long ago, as you want it written: "2m". */
  time?: string;
  /** The placeholder of the reply field. "Reply to" followed by the author's first name when left out. */
  replyPlaceholder?: string;
}

/** A small activity toast: something that just happened. */
export interface ActivitySnippet {
  /** Tells the card kinds apart. */
  kind: "activity";
  /** What happened, as a whole sentence: "Priya completed Design handoff". */
  text: string;
  /** When, as you want it written: "just now". */
  time?: string;
}

/** A status card: a name, where it stands and how far along it is. */
export interface StatusSnippet {
  /** Tells the card kinds apart. */
  kind: "status";
  /** What the status is of: "Sprint 24". */
  title: string;
  /** Where it stands, in a word or two: "On track". */
  status: string;
  /** How far along, from 0 to 100. */
  progress: number;
  /** A line under the bar: "18 of 25 tasks done". */
  detail?: string;
}

export type Snippet = TaskSnippet | CommentSnippet | ActivitySnippet | StatusSnippet;

function Person({ person, size = "sm" }: { person: SnippetPerson; size?: "sm" | "default" }) {
  return (
    <Avatar size={size} className="ring-2 ring-card">
      {person.src ? <AvatarImage src={person.src} alt="" /> : null}
      <AvatarFallback>{initialsOf(person.name)}</AvatarFallback>
    </Avatar>
  );
}

/** What a screen reader hears for one card. The cards themselves are drawings, so this is all there is of them. */
export function describeSnippet(snippet: Snippet): string {
  switch (snippet.kind) {
    case "task":
      return `A task, ${snippet.title}, ${snippet.done ? "done, " : ""}assigned to ${snippet.assignee.name}, due ${snippet.due}.`;
    case "comment":
      return `${snippet.author.name} comments: ${snippet.text}`;
    case "activity":
      return `${snippet.text}.`;
    case "status":
      return `${snippet.title} is ${snippet.status.toLowerCase()}, ${Math.round(snippet.progress)} percent done.`;
  }
}

const SURFACE = "w-full rounded-xl border border-border bg-card p-3.5 text-start text-sm leading-snug text-card-foreground shadow-sm";

/** One drawn card. It is made of the same checkbox, badge and avatar a product would use, so it looks like the product and nothing else. */
export function SnippetCard({ snippet, className }: { snippet: Snippet; className?: string }) {
  if (snippet.kind === "task") {
    return (
      <div className={cn(SURFACE, className)}>
        <div className="flex items-start gap-2.5">
          <Checkbox checked={Boolean(snippet.done)} tabIndex={-1} className="mt-0.5" />
          <p className={cn("min-w-0 flex-1 font-medium text-pretty", snippet.done && "text-muted-foreground line-through decoration-muted-foreground/60")}>{snippet.title}</p>
        </div>
        <div className="mt-3 flex items-center gap-2 ps-7">
          {snippet.label ? <Badge variant="outline">{snippet.label}</Badge> : null}
          <span className="inline-flex items-center gap-1 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
            <IconCalendar className="size-3.5" />
            {snippet.due}
          </span>
          <span className="ms-auto">
            <Person person={snippet.assignee} />
          </span>
        </div>
      </div>
    );
  }
  if (snippet.kind === "comment") {
    const first = snippet.author.name.split(/\s+/)[0] ?? snippet.author.name;
    return (
      <div className={cn(SURFACE, className)}>
        <div className="flex items-center gap-2.5">
          <Person person={snippet.author} />
          <p className="min-w-0 truncate font-medium">{snippet.author.name}</p>
          {snippet.time ? <p className="ms-auto text-xs whitespace-nowrap text-muted-foreground">{snippet.time}</p> : null}
        </div>
        <p className="mt-2.5 text-pretty text-card-foreground/90">{snippet.text}</p>
        <div className="mt-3 flex items-center gap-2 rounded-md border border-input bg-background py-1.5 pe-1.5 ps-2.5 text-xs text-muted-foreground shadow-xs">
          <span className="min-w-0 flex-1 truncate">{snippet.replyPlaceholder ?? `Reply to ${first}`}</span>
          <span className="grid size-6 shrink-0 place-items-center rounded bg-primary text-primary-foreground">
            <IconSend className="size-3" />
          </span>
        </div>
      </div>
    );
  }
  if (snippet.kind === "activity") {
    return (
      <div className={cn(SURFACE, "flex items-center gap-3 py-3 pe-4 ps-3", className)}>
        <span className="grid size-7 shrink-0 place-items-center rounded-full bg-primary text-primary-foreground">
          <IconCheck className="size-3.5" />
        </span>
        <p className="min-w-0">
          <span className="block font-medium text-pretty">{snippet.text}</span>
          {snippet.time ? <span className="block text-xs text-muted-foreground">{snippet.time}</span> : null}
        </p>
      </div>
    );
  }
  const progress = Math.min(100, Math.max(0, snippet.progress));
  return (
    <div className={cn(SURFACE, className)}>
      <div className="flex items-center justify-between gap-3">
        <p className="min-w-0 truncate font-medium">{snippet.title}</p>
        <Badge variant="secondary">
          <span aria-hidden="true" className="size-1.5 rounded-full bg-current" />
          {snippet.status}
        </Badge>
      </div>
      <div className="mt-3.5 h-1.5 overflow-hidden rounded-full bg-muted">
        <div className="h-full rounded-full bg-primary" style={{ width: `${progress}%` }} />
      </div>
      <p className="mt-2 flex justify-between gap-3 text-xs text-muted-foreground tabular-nums">
        <span>{snippet.detail}</span>
        <span>{Math.round(progress)}%</span>
      </p>
    </div>
  );
}
